  "inlineSchema": "// Parcela SSCC – Reservation System Schema\n// Prisma v7 / PostgreSQL\n// Datasource URL is configured in prisma.config.ts (v7 requirement)\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─────────────────────────────────────────\n// Enums\n// ─────────────────────────────────────────\n\nenum Role {\n  SOCIO\n  ADMIN\n  GUARDIA\n}\n\nenum ReservationStatus {\n  PENDIENTE_PAGO\n  CONFIRMADA\n  COMPLETADA\n  CANCELADA\n}\n\nenum PaymentStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  REFUNDED\n}\n\n// ─────────────────────────────────────────\n// Models\n// ─────────────────────────────────────────\n\nmodel User {\n  id           String   @id @default(cuid())\n  email        String   @unique\n  rut          String?  @unique\n  passwordHash String\n  role         Role     @default(SOCIO)\n  createdAt    DateTime @default(now())\n\n  // Back-reference: the family this user owns (populated via Family.ownerId)\n  ownedFamily Family? @relation(\"FamilyOwner\")\n\n  // Family members that have a user account\n  familyMember FamilyMember[]\n\n  // Fines issued by this user (admin)\n  finesIssued Fine[] @relation(\"FineIssuer\")\n\n  @@map(\"users\")\n}\n\nmodel Family {\n  id        String   @id @default(cuid())\n  name      String\n  createdAt DateTime @default(now())\n\n  // The SOCIO who owns this family record (optional: imported nuclei may have no owner yet)\n  ownerId String? @unique\n  owner   User?   @relation(\"FamilyOwner\", fields: [ownerId], references: [id])\n\n  // Import traceability\n  importKey  String?   @unique\n  importedAt DateTime?\n\n  members      FamilyMember[]\n  reservations Reservation[]\n  fines        Fine[]\n\n  @@map(\"families\")\n}\n\nmodel FamilyMember {\n  id        String   @id @default(cuid())\n  fullName  String\n  relation  String // e.g. \"titular\", \"cónyuge\", \"hijo\", etc.\n  rut       String?\n  email     String?\n  course    String?\n  exAlumno  Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  familyId String\n  family   Family @relation(fields: [familyId], references: [id])\n\n  // Optional: this member may also have their own login\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id])\n\n  fines Fine[]\n\n  @@map(\"family_members\")\n}\n\nmodel AddOnSpace {\n  id             String   @id @default(cuid())\n  name           String   @unique // quincho | sala_eventos | sala_cafeteria | quincho_libre\n  pricePerUnit   Int      @default(0) // CLP, placeholder\n  capacityGuests Int? // null = no limit (e.g. quincho)\n  dailyLimit     Int? // max units bookable per day (null = unlimited)\n  createdAt      DateTime @default(now())\n\n  reservationAddOns ReservationAddOn[]\n\n  @@map(\"add_on_spaces\")\n}\n\nmodel Reservation {\n  id          String            @id @default(cuid())\n  date        DateTime          @db.Date // full-day booking; multiple families may share same date\n  status      ReservationStatus @default(PENDIENTE_PAGO)\n  totalAmount Int               @default(0) // CLP\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n  remindedAt  DateTime?\n\n  familyId String\n  family   Family @relation(fields: [familyId], references: [id])\n\n  addOns       ReservationAddOn[]\n  extraPersons ExtraPerson[]\n  payments     Payment[]\n  qrTokens     QrToken[]\n  visits       Visit[]\n\n  // One family cannot book the same day twice\n  @@unique([familyId, date])\n  @@map(\"reservations\")\n}\n\nmodel ReservationAddOn {\n  id       String @id @default(cuid())\n  quantity Int    @default(1)\n\n  reservationId String\n  reservation   Reservation @relation(fields: [reservationId], references: [id])\n\n  addOnSpaceId String\n  addOnSpace   AddOnSpace @relation(fields: [addOnSpaceId], references: [id])\n\n  @@map(\"reservation_add_ons\")\n}\n\nmodel ExtraPerson {\n  id       String  @id @default(cuid())\n  fullName String\n  rut      String?\n  isSocio  Boolean @default(false) // socio de otro núcleo: no paga entrada\n  usesPool Boolean @default(false) // extra charge if pool is used\n\n  reservationId String\n  reservation   Reservation @relation(fields: [reservationId], references: [id])\n\n  @@map(\"extra_persons\")\n}\n\nmodel Payment {\n  id                String        @id @default(cuid())\n  provider          String // e.g. \"mercadopago\"\n  providerPaymentId String?       @unique\n  amount            Int // CLP\n  status            PaymentStatus @default(PENDING)\n  paidAt            DateTime?\n  createdAt         DateTime      @default(now())\n\n  reservationId String\n  reservation   Reservation @relation(fields: [reservationId], references: [id])\n\n  @@map(\"payments\")\n}\n\nmodel QrToken {\n  id        String    @id @default(cuid())\n  token     String    @unique @default(cuid())\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  reservationId String\n  reservation   Reservation @relation(fields: [reservationId], references: [id])\n\n  @@map(\"qr_tokens\")\n}\n\nmodel Fine {\n  id        String    @id @default(cuid())\n  reason    String\n  amount    Int // CLP\n  paidAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  familyId String\n  family   Family @relation(fields: [familyId], references: [id])\n\n  // Optional: against a specific member\n  familyMemberId String?\n  familyMember   FamilyMember? @relation(fields: [familyMemberId], references: [id])\n\n  // Admin who issued the fine\n  issuedById String\n  issuedBy   User   @relation(\"FineIssuer\", fields: [issuedById], references: [id])\n\n  @@map(\"fines\")\n}\n\nmodel Visit {\n  id          String   @id @default(cuid())\n  checkedInAt DateTime @default(now())\n  checkedInBy String // userId of the admin / gate guard\n\n  reservationId String\n  reservation   Reservation @relation(fields: [reservationId], references: [id])\n\n  @@map(\"visits\")\n}\n\nmodel AppSetting {\n  key   String @id\n  value String\n\n  @@map(\"app_settings\")\n}\n",
